import { MakeLogicType, actions, afterMount, kea, listeners, path, reducers } from 'kea'
import posthog from 'posthog-js'

import { lemonToast } from '@posthog/lemon-ui'

import { teamLogic } from 'scenes/teamLogic'

import { errorTrackingRecommendationsList, errorTrackingRecommendationsRefreshCreate } from '../../../generated/api'
import type { ErrorTrackingRecommendationApi } from '../../../generated/api.schemas'

const POLL_INTERVAL_MS = 500

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface recommendationsLogicValues {
    recommendations: ErrorTrackingRecommendationApi[]
    recommendationsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface recommendationsLogicActions {
    ensurePollingScheduled: () => {
        value: true
    }
    loadRecommendations: () => {
        value: true
    }
    markRecommendationComputing: (id: string) => {
        id: string
    }
    pollRecommendations: () => {
        value: true
    }
    refreshRecommendation: (id: string) => {
        id: string
    }
    setRecommendations: (recommendations: ErrorTrackingRecommendationApi[]) => {
        recommendations: ErrorTrackingRecommendationApi[]
    }
    setRecommendationsLoading: (loading: boolean) => {
        loading: boolean
    }
    upsertRecommendation: (recommendation: ErrorTrackingRecommendationApi) => {
        recommendation: ErrorTrackingRecommendationApi
    }
}

export type recommendationsLogicType = MakeLogicType<recommendationsLogicValues, recommendationsLogicActions>

// The backend `status` field is the single source of truth for "is this recommendation
// being computed". The frontend optimistically flips status to 'computing' before issuing
// a refresh HTTP call, and polls until no recommendation is computing. The optimistic value
// converges with the server response since both arrive at status='computing'.
export const recommendationsLogic = kea<recommendationsLogicType>([
    path(['products', 'error_tracking', 'scenes', 'ErrorTrackingScene', 'banners', 'recommendationsLogic']),

    actions({
        loadRecommendations: true,
        pollRecommendations: true,
        refreshRecommendation: (id: string) => ({ id }),

        setRecommendations: (recommendations: ErrorTrackingRecommendationApi[]) => ({ recommendations }),
        upsertRecommendation: (recommendation: ErrorTrackingRecommendationApi) => ({ recommendation }),
        markRecommendationComputing: (id: string) => ({ id }),
        setRecommendationsLoading: (loading: boolean) => ({ loading }),

        ensurePollingScheduled: true,
    }),

    reducers({
        recommendations: [
            [] as ErrorTrackingRecommendationApi[],
            {
                setRecommendations: (_, { recommendations }) => recommendations,
                upsertRecommendation: (state, { recommendation }) =>
                    state.map((r) => (r.id === recommendation.id ? recommendation : r)),
                markRecommendationComputing: (state, { id }) =>
                    state.map((r) => (r.id === id ? { ...r, status: 'computing' } : r)),
            },
        ],
        recommendationsLoading: [
            true,
            {
                setRecommendationsLoading: (_, { loading }) => loading,
            },
        ],
    }),

    listeners(({ actions, values, cache }) => ({
        loadRecommendations: async () => {
            actions.setRecommendationsLoading(true)
            try {
                const response = await errorTrackingRecommendationsList(String(teamLogic.values.currentTeamId))
                actions.setRecommendations(response.results)
                posthog.capture('error_tracking_recommendations_loaded', {
                    open_count: response.results.filter((r) => !r.dismissed_at && !r.completed).length,
                    completed_count: response.results.filter((r) => !r.dismissed_at && r.completed).length,
                    dismissed_count: response.results.filter((r) => !!r.dismissed_at).length,
                    total_count: response.results.length,
                })
            } finally {
                actions.setRecommendationsLoading(false)
            }
        },
        pollRecommendations: async () => {
            try {
                const response = await errorTrackingRecommendationsList(String(teamLogic.values.currentTeamId), {
                    poll: true,
                })
                actions.setRecommendations(response.results)
            } catch {
                actions.ensurePollingScheduled()
            }
        },
        refreshRecommendation: async ({ id }) => {
            actions.markRecommendationComputing(id)
            try {
                const updated = await errorTrackingRecommendationsRefreshCreate(
                    String(teamLogic.values.currentTeamId),
                    id
                )
                actions.upsertRecommendation(updated)
            } catch {
                lemonToast.error("Couldn't refresh your error tracking setup. Reload the page to try again.")
                // Polling will reconcile state regardless of which side errored.
            }
        },

        // Polling lifecycle: any time the recommendations state changes, re-evaluate
        // whether we still need to poll. The shared key keeps one timer at a time.
        setRecommendations: () => actions.ensurePollingScheduled(),
        upsertRecommendation: () => actions.ensurePollingScheduled(),
        markRecommendationComputing: () => actions.ensurePollingScheduled(),
        ensurePollingScheduled: () => {
            if (!values.recommendations.some((r) => r.status === 'computing')) {
                cache.disposables.dispose('poll')
                return
            }
            cache.disposables.add(() => {
                const timeoutId = window.setTimeout(() => actions.pollRecommendations(), POLL_INTERVAL_MS)
                return () => window.clearTimeout(timeoutId)
            }, 'poll')
        },
    })),

    afterMount(({ actions }) => {
        actions.loadRecommendations()
    }),
])
